:root {
  --navy: #0f2440;
  --navy-2: #16305a;
  --ink: #1c2b3a;
  --paper: #ffffff;
  --wash: #eef2f7;
  --line: #d7e0ec;
  --accent: #e8930c;
  --accent-ink: #7a4a00;
  --good: #1e7e34;
  --muted: #5b6b7f;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--ink);
  background: var(--wash);
  line-height: 1.5;
}
.wrap { max-width: 1080px; margin: 0 auto; padding: 0 20px; }
.fiction-banner {
  background: var(--accent);
  color: #231600;
  text-align: center;
  font-weight: 700;
  padding: 8px 12px;
  font-size: 0.95rem;
}
.site-header {
  background: var(--navy);
  color: #fff;
  padding: 28px 0 24px;
}
.site-header h1 { margin: 0 0 6px; font-size: 1.7rem; }
.site-header .portal { font-weight: 400; color: #b9c7da; font-size: 1.15rem; }
.subtitle { margin: 0; color: #cdd8e8; max-width: 60ch; }
.header-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.badge {
  white-space: nowrap;
  border: 2px solid var(--accent);
  color: #ffd98a;
  border-radius: 999px;
  padding: 6px 14px;
  font-weight: 700;
  font-size: 0.85rem;
}
section { margin: 32px 0; }
h2 {
  color: var(--navy);
  border-bottom: 3px solid var(--accent);
  display: inline-block;
  padding-bottom: 4px;
  margin-bottom: 16px;
}
.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 16px; }
.cards.two-col { grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); margin-top: 16px; }
.card {
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 4px solid var(--navy-2);
  border-radius: 10px;
  padding: 16px 18px;
}
.card.accent { border-top-color: var(--accent); }
.card h3 { margin: 0 0 8px; color: var(--navy); }
.card p { margin: 6px 0; }
.status { font-weight: 700; }
.status.live { color: var(--good); }
.status.wait { color: var(--accent-ink); }
.programmes { color: var(--muted); }
table { border-collapse: collapse; width: 100%; background: #fff; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); font-size: 0.93rem; }
thead th { background: var(--navy); color: #fff; }
tbody tr:hover { background: #f6f9fd; }
.pill {
  display: inline-block;
  border-radius: 999px;
  padding: 2px 12px;
  font-size: 0.82rem;
  font-weight: 700;
  background: #e3e9f1;
  color: var(--navy-2);
}
.pill.pass { background: #dff0e2; color: var(--good); }
.pill.open, .pill.draft { background: #fdf0d7; color: var(--accent-ink); }
.parts-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 16px; }
.part-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}
.part-card img { width: 100%; height: 220px; object-fit: contain; background: #f7fafd; border-bottom: 1px solid var(--line); }
.part-body { padding: 12px 14px 14px; }
.part-body h3 { margin: 0 0 2px; color: var(--navy); font-size: 1.05rem; }
.part-body .meta { color: var(--muted); font-size: 0.86rem; margin: 2px 0 8px; }
.part-body pre {
  display: none;
  background: var(--navy);
